    display: flex;
    gap: 2px;
    position: absolute;
    top: -8px;
    right: 8px;
    background: #1a1d21;
    border: 1px solid #444;
    border-radius: 6px;
    padding: 2px;
    box-shadow: 0 2px 8px rgba(0,0,0,.4);
