}

.action-btn {
    background: none;
    border: none;
    color: #d1d2d3;
    font-size: 0.78rem;
    padding: 4px 8px;
    border-radius: 4px;
    cursor: pointer;
    white-space: nowrap;
}

.action-btn:hover {
    background: #333;
}

/* ── Emoji Picker ────────────────────────────────────────────── */
.emoji-picker-wrapper {
    position: relative;
}

.emoji-picker {
    position: absolute;
    top: 100%;
    right: 0;
    background: #2c2d30;
    border: 1px solid #444;
    border-radius: 8px;
    padding: 6px;
    display: flex;
    gap: 2px;
    box-shadow: 0 4px 12px rgba(0,0,0,.5);
    z-index: 20;
}

.emoji-option {
    background: none;
    border: none;
    font-size: 1.25rem;
    cursor: pointer;
    padding: 4px 6px;
    border-radius: 4px;
    transition: background 0.15s;
}

.emoji-option:hover {
    background: #444;
}

/* ── Compose Area ────────────────────────────────────────────── */
.compose-area {
    display: flex;
    gap: 8px;
    padding: 12px 20px;
    border-top: 1px solid #333;
    flex-shrink: 0;
}

.compose-input {
    flex: 1;
    background: #222529;
    border: 1px solid #444;
    border-radius: 6px;
    padding: 8px 12px;
    color: #d1d2d3;
    font-size: 0.9rem;
    resize: none;
    min-height: 40px;
    max-height: 120px;
    font-family: inherit;
}

.compose-input:focus {
    outline: none;
    border-color: #1264a3;
}

.compose-input::placeholder {
    color: #717274;
}

.send-btn {
    background: #007a5a;
    color: #fff;
    border: none;
    border-radius: 6px;
    padding: 8px 16px;
    font-weight: 600;
    font-size: 0.85rem;
    cursor: pointer;
    align-self: flex-end;
    transition: background 0.15s;
}

.send-btn:hover:not(:disabled) {
    background: #148567;
}

.send-btn:disabled {
    opacity: 0.4;
    cursor: default;
}

/* ── Thread Panel ────────────────────────────────────────────── */
.thread-panel {
    width: 25%;
    min-width: 260px;
    max-width: 400px;
    background: #222529;
    border-left: 1px solid #333;
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px;
    border-bottom: 1px solid #333;
    flex-shrink: 0;
}

.thread-header h4 {
    margin: 0;
    font-size: 1rem;
    font-weight: 700;
    color: #fff;
}

.close-btn {
    background: none;
    border: none;
    color: #9a9b9e;
    font-size: 1.1rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
}

.close-btn:hover {
    background: #333;
    color: #fff;
}

.thread-root-quote {
    padding: 12px 16px;
    border-bottom: 1px solid #333;
    background: #2c2d30;
    flex-shrink: 0;
}

.thread-root-quote .msg-body {
    margin-top: 4px;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 8px 16px;
}

.thread-reply {
    padding: 6px 0;
}

.thread-panel .compose-area {
    padding: 12px 16px;
}

/* ── Scrollbar styling ───────────────────────────────────────── */
.message-list::-webkit-scrollbar,
.thread-replies::-webkit-scrollbar,
.channel-list::-webkit-scrollbar {
    width: 6px;
}

.message-list::-webkit-scrollbar-track,
.thread-replies::-webkit-scrollbar-track,
.channel-list::-webkit-scrollbar-track {
    background: transparent;
}

.message-list::-webkit-scrollbar-thumb,
.thread-replies::-webkit-scrollbar-thumb,
.channel-list::-webkit-scrollbar-thumb {
    background: #555;
    border-radius: 3px;
}

@page "/chat"
@layout ChatLayout
@using sv_b4d6047afcca43ae91755c94bc025561.Services
@inject IChatService ChatService
@inject IJSRuntime JS
@rendermode InteractiveServer

<div class="chat-container">
    @* ===== LEFT SIDEBAR — Channel List ===== *@
    <aside class="channel-sidebar">
        <div class="sidebar-header">
            <h2>Channels</h2>
        </div>
        <ul class="channel-list">
            @if (_channels is not null)
            {
                @foreach (var channel in _channels)
                {
                    <li class="channel-item @(channel.Id == _activeChannelId ? "active" : "")"
                        @onclick="() => SelectChannelAsync(channel)">
                        <div class="channel-name"># @channel.Name</div>
                        <div class="channel-desc">@TruncateDescription(channel.Description)</div>
                        @if (channel.UnreadCount > 0)
                        {
                            <span class="unread-badge">@channel.UnreadCount</span>
                        }
                    </li>
                }
            }
        </ul>
    </aside>

    @* ===== MAIN MESSAGE AREA ===== *@
    <section class="message-area @(_threadOpen ? "" : "expanded")">
        @if (_activeChannel is not null)
        {
            <div class="message-header">
                <h3># @_activeChannel.Name</h3>
                <span class="header-desc">@_activeChannel.Description</span>
            </div>

            <div class="message-list" @ref="_messageListRef" @onscroll="OnMessageListScroll">
                @if (_loadingOlder)
                {
                    <div class="loading-indicator">Loading older messages…</div>
                }
                @if (_messages is not null)
                {
                    @foreach (var msg in _messages)
                    {
                        <div class="message-row" @onmouseenter="() => _hoveredMessageId = msg.Id"
                             @onmouseleave="() => _hoveredMessageId = null">
                            <div class="message-content-wrapper">
                                <div class="message-meta">
                                    <span class="msg-author">@msg.Author</span>
                                    <span class="msg-time">@FormatRelativeTime(msg.SentAt)</span>
                                </div>
                                <div class="msg-body">@msg.Content</div>

                                @if (msg.Reactions.Count > 0)
                                {
                                    <div class="reaction-row">
                                        @foreach (var r in msg.Reactions)
                                        {
                                            <button class="reaction-badge" title="@string.Join(", ", r.Users)"
                                                    @onclick="() => ToggleReactionAsync(msg.Id, r.Emoji)">
                                                @r.Emoji @r.Users.Count
                                            </button>
                                        }
                                    </div>
                                }

                                @{
                                    var thread = _threadSummaries.GetValueOrDefault(msg.Id);
                                }
                                @if (thread is not null)
                                {
                                    <button class="thread-link" @onclick="() => OpenThreadAsync(msg.Id)">
                                        @thread.ReplyCount @(thread.ReplyCount == 1 ? "reply" : "replies")
                                        — last @FormatRelativeTime(thread.LastReplyAt)
                                    </button>
                                }
                            </div>

                            @if (_hoveredMessageId == msg.Id)
                            {
                                <div class="message-actions">
                                    <button class="action-btn" title="Reply in thread"
                                            @onclick="() => OpenThreadAsync(msg.Id)">💬 Reply</button>
                                    <div class="emoji-picker-wrapper">
                                        <button class="action-btn" title="Add reaction"
                                                @onclick="() => ToggleEmojiPicker(msg.Id)">😀 React</button>
                                        @if (_emojiPickerMessageId == msg.Id)
                                        {
                                            <div class="emoji-picker">
                                                @foreach (var emoji in _commonEmojis)
                                                {
                                                    <button class="emoji-option"
                                                            @onclick="() => PickEmojiAsync(msg.Id, emoji)">@emoji</button>
                                                }
                                            </div>
                                        }
                                    </div>
                                </div>
                            }
                        </div>
                    }
                }
            </div>

            <div class="compose-area">
                <textarea class="compose-input" placeholder="Message #@_activeChannel.Name"
                          @bind="_newMessageText" @bind:event="oninput"
                          @onkeydown="OnComposeKeyDown"></textarea>
                <button class="send-btn" @onclick="SendMessageAsync" disabled="@string.IsNullOrWhiteSpace(_newMessageText)">
                    Send
                </button>
            </div>
        }
        else
        {
            <div class="empty-state">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </section>

    @* ===== RIGHT PANEL — Thread View ===== *@
    @if (_threadOpen && _threadRootMessage is not null)
    {
        <aside class="thread-panel">
            <div class="thread-header">
                <h4>Thread</h4>
                <button class="close-btn" @onclick="CloseThread" title="Close thread">✕</button>
            </div>

            <div class="thread-root-quote">
                <span class="msg-author">@_threadRootMessage.Author</span>
                <span class="msg-time">@FormatRelativeTime(_threadRootMessage.SentAt)</span>
                <div class="msg-body">@_threadRootMessage.Content</div>
            </div>

            <div class="thread-replies" @ref="_threadListRef">
                @if (_threadMessages is not null)
                {
                    @foreach (var reply in _threadMessages)
                    {
                        <div class="message-row thread-reply">
                            <div class="message-content-wrapper">
                                <div class="message-meta">
                                    <span class="msg-author">@reply.Author</span>
                                    <span class="msg-time">@FormatRelativeTime(reply.SentAt)</span>
                                </div>
                                <div class="msg-body">@reply.Content</div>

                                @if (reply.Reactions.Count > 0)
                                {
                                    <div class="reaction-row">
                                        @foreach (var r in reply.Reactions)
                                        {
                                            <button class="reaction-badge"
                                                    @onclick="() => ToggleReactionAsync(reply.Id, r.Emoji)">
                                                @r.Emoji @r.Users.Count
                                            </button>
                                        }
                                    </div>
                                }
                            </div>
                        </div>
                    }
                }
            </div>

            <div class="compose-area">
                <textarea class="compose-input" placeholder="Reply…"
                          @bind="_threadReplyText" @bind:event="oninput"
                          @onkeydown="OnThreadReplyKeyDown"></textarea>
                <button class="send-btn" @onclick="SendThreadReplyAsync"
                        disabled="@string.IsNullOrWhiteSpace(_threadReplyText)">
                    Reply
                </button>
            </div>
        </aside>
    }
</div>

@code {
    private const int PageSize = 30;
    private static readonly string[] _commonEmojis = ["👍", "❤️", "😂", "🎉", "🚀", "👀"];

    // Data
    private List<Channel>? _channels;
    private List<Message>? _messages;
    private List<Message>? _threadMessages;
    private Dictionary<int, ThreadSummary> _threadSummaries = new();

    // Active state
    private int? _activeChannelId;
    private Channel? _activeChannel;
    private int? _hoveredMessageId;
    private int? _emojiPickerMessageId;
    private bool _threadOpen;
    private int? _threadRootId;
    private Message? _threadRootMessage;

    // Compose state
    private string _newMessageText = "";
    private string _threadReplyText = "";

    // Pagination
    private int _skip;
    private bool _loadingOlder;
    private bool _allLoaded;

    // Element references
    private ElementReference _messageListRef;
    private ElementReference _threadListRef;

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();

        if (_channels.Count > 0)
        {
            await SelectChannelAsync(_channels[0]);
        }
    }

    // ── Channel selection ──────────────────────────────────────────

    private async Task SelectChannelAsync(Channel channel)
    {
        if (channel.Id == _activeChannelId) return;

        _activeChannelId = channel.Id;
        _activeChannel = channel;
        _skip = 0;
        _allLoaded = false;
        _messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        _skip = _messages.Count;

        BuildThreadSummaries();
        await ChatService.MarkChannelReadAsync(channel.Id);
        RefreshChannelUnread(channel.Id);
        CloseThread();

        StateHasChanged();
        await ScrollToBottomAsync();
    }

    private void RefreshChannelUnread(int channelId)
    {
        if (_channels is null) return;
        var idx = _channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            var c = _channels[idx];
            _channels[idx] = c with { UnreadCount = 0 };
        }
    }

    // ── Messages ───────────────────────────────────────────────────

    private async Task SendMessageAsync()
    {
        if (string.IsNullOrWhiteSpace(_newMessageText) || _activeChannelId is null) return;

        var msg = await ChatService.SendMessageAsync(_activeChannelId.Value, _newMessageText.Trim(), null);
        _messages ??= new();
        _messages.Add(msg);
        _skip++;
        _newMessageText = "";
        StateHasChanged();
        await ScrollToBottomAsync();
    }

    private async Task OnComposeKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await SendMessageAsync();
        }
    }

    // ── Load older messages on scroll-to-top ───────────────────────

    private async Task OnMessageListScroll()
    {
        if (_loadingOlder || _allLoaded || _activeChannelId is null) return;

        var scrollTop = await JS.InvokeAsync<double>("eval", "document.querySelector('[b-chat-scroll]')?.scrollTop ?? 1");
        if (scrollTop > 5) return;

        _loadingOlder = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(_activeChannelId.Value, _skip, PageSize);
        if (older.Count == 0)
        {
            _allLoaded = true;
        }
        else
        {
            _messages!.InsertRange(0, older);
            _skip += older.Count;
            BuildThreadSummaries();
        }

        _loadingOlder = false;
        StateHasChanged();
    }

    // ── Reactions ──────────────────────────────────────────────────

    private void ToggleEmojiPicker(int messageId)
    {
        _emojiPickerMessageId = _emojiPickerMessageId == messageId ? null : messageId;
    }

    private async Task PickEmojiAsync(int messageId, string emoji)
    {
        _emojiPickerMessageId = null;
        await ToggleReactionAsync(messageId, emoji);
    }

    private async Task ToggleReactionAsync(int messageId, string emoji)
    {
        await ChatService.AddReactionAsync(messageId, emoji);

        // Refresh the message list to reflect the new reaction
        if (_activeChannelId is not null && _messages is not null)
        {
            var idx = _messages.FindIndex(m => m.Id == messageId);
            if (idx >= 0)
            {
                var updated = await ChatService.GetMessagesAsync(_activeChannelId.Value, 0, _skip);
                _messages = updated;
                BuildThreadSummaries();
            }
        }

        // Also refresh thread messages if thread is open
        if (_threadMessages is not null)
        {
            var tidx = _threadMessages.FindIndex(m => m.Id == messageId);
            if (tidx >= 0 && _threadRootId is not null)
            {
                _threadMessages = await ChatService.GetThreadAsync(_threadRootId.Value);
            }
        }

        StateHasChanged();
    }

    // ── Thread panel ───────────────────────────────────────────────

    private async Task OpenThreadAsync(int rootMessageId)
    {
        _threadRootId = rootMessageId;
        _threadRootMessage = _messages?.FirstOrDefault(m => m.Id == rootMessageId);
        _threadMessages = await ChatService.GetThreadAsync(rootMessageId);
        _threadReplyText = "";
        _threadOpen = true;
        _emojiPickerMessageId = null;
        StateHasChanged();
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootId = null;
        _threadRootMessage = null;
        _threadMessages = null;
        _threadReplyText = "";
    }

    private async Task SendThreadReplyAsync()
    {
        if (string.IsNullOrWhiteSpace(_threadReplyText) || _activeChannelId is null || _threadRootId is null) return;

        var reply = await ChatService.SendMessageAsync(_activeChannelId.Value, _threadReplyText.Trim(), _threadRootId);
        _threadMessages ??= new();
        _threadMessages.Add(reply);
        _threadReplyText = "";

        // Update the thread summary count in the main message list
        BuildThreadSummaries();
        StateHasChanged();
    }

    private async Task OnThreadReplyKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await SendThreadReplyAsync();
        }
    }

    // ── Thread summary helpers ─────────────────────────────────────

    private void BuildThreadSummaries()
    {
        if (_messages is null) return;
        _threadSummaries.Clear();

        // Group replies by their root message
        var replies = _messages.Where(m => m.ReplyToId is not null).ToList();
        foreach (var group in replies.GroupBy(m => m.ReplyToId!.Value))
        {
            _threadSummaries[group.Key] = new ThreadSummary(
                group.Key,
                group.Count(),
                group.Max(m => m.SentAt)
            );
        }
    }

    // ── Formatting helpers ─────────────────────────────────────────

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt.ToUniversalTime();
        if (diff.TotalSeconds < 60) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return sentAt.ToString("MMM d, yyyy");
    }

    private static string TruncateDescription(string desc)
    {
        return desc.Length > 40 ? desc[..37] + "…" : desc;
    }

    private async Task ScrollToBottomAsync()
    {
        try
        {
            await Task.Yield();
            await JS.InvokeVoidAsync("eval",
                "setTimeout(() => { const el = document.querySelector('[b-chat-scroll]'); if(el) el.scrollTop = el.scrollHeight; }, 50)");
        }
        catch { /* Element may not be rendered yet */ }
    }
}

