.thread-link {
    background: none;
    border: none;
    color: #1d9bd1;
    font-size: 0.78rem;
    cursor: pointer;
    padding: 2px 0;
    margin-top: 2px;
}

.thread-link:hover {
    text-decoration: underline;
}

