    position: absolute;
    top: 100%;
    right: 0;
    background: #2c2d30;
    border: 1px solid #444;
    border-radius: 8px;
    padding: 6px;
    display: flex;
    gap: 2px;
    box-shadow: 0 4px 12px rgba(0,0,0,.5);
    z-index: 20;
}

.emoji-option {
    background: none;
    border: none;
    font-size: 1.25rem;
    cursor: pointer;
    padding: 4px 6px;
    border-radius: 4px;
    transition: background 0.15s;
}

.emoji-option:hover {
    background: #444;
}

/* ── Compose Area ────────────────────────────────────────────── */
