/* ── Layout Shell ─────────────────────────────────────────────── */
.chat-container {
    display: flex;
    height: 100vh;
    width: 100%;
    font-family: 'Segoe UI', -apple-system, BlinkMacSystemFont, sans-serif;
    background: #1a1d21;
    color: #d1d2d3;
}

/* ── Channel Sidebar ─────────────────────────────────────────── */
.channel-sidebar {
    width: 20%;
    min-width: 200px;
    max-width: 280px;
    background: #19171d;
    border-right: 1px solid #333;
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

.sidebar-header {
    padding: 16px 16px 8px;
    border-bottom: 1px solid #333;
}

.sidebar-header h2 {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 700;
    color: #fff;
}

.channel-list {
    list-style: none;
    margin: 0;
    padding: 8px 0;
    overflow-y: auto;
    flex: 1;
}

.channel-item {
    padding: 8px 16px;
    cursor: pointer;
    position: relative;
    border-radius: 4px;
    margin: 0 8px;
    transition: background 0.15s;
}

.channel-item:hover {
    background: #27242c;
}

.channel-item.active {
    background: #1264a3;
    color: #fff;
}

.channel-name {
    font-weight: 600;
    font-size: 0.95rem;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.channel-desc {
    font-size: 0.75rem;
    color: #9a9b9e;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    margin-top: 2px;
}

.channel-item.active .channel-desc {
    color: rgba(255,255,255,.7);
}

.unread-badge {
    position: absolute;
    right: 12px;
    top: 50%;
    transform: translateY(-50%);
    background: #e01e5a;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 2px 7px;
    border-radius: 10px;
    min-width: 20px;
    text-align: center;
}

/* ── Main Message Area ───────────────────────────────────────── */
.message-area {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
    background: #1a1d21;
    transition: flex 0.2s;
}

.message-area.expanded {
    flex: 1 1 80%;
}

.message-header {
    padding: 12px 20px;
    border-bottom: 1px solid #333;
    flex-shrink: 0;
}

.message-header h3 {
    margin: 0;
    font-size: 1.05rem;
    font-weight: 700;
    color: #fff;
}

.header-desc {
    font-size: 0.8rem;
    color: #9a9b9e;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 12px 20px;
}

.loading-indicator {
    text-align: center;
    padding: 12px;
    color: #9a9b9e;
    font-size: 0.85rem;
}

.empty-state {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100%;
    color: #9a9b9e;
    font-size: 1rem;
}

/* ── Message Row ─────────────────────────────────────────────── */
.message-row {
    display: flex;
    align-items: flex-start;
    padding: 6px 4px;
    border-radius: 6px;
    position: relative;
    gap: 8px;
}

.message-row:hover {
    background: #222529;
}

.message-content-wrapper {
    flex: 1;
    min-width: 0;
}

.message-meta {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.msg-author {
    font-weight: 700;
    font-size: 0.9rem;
    color: #fff;
}

.msg-time {
    font-size: 0.72rem;
    color: #717274;
}

.msg-body {
    font-size: 0.9rem;
    line-height: 1.45;
    word-break: break-word;
}

/* ── Reactions ───────────────────────────────────────────────── */
.reaction-row {
    display: flex;
    flex-wrap: wrap;
