+/* ── Emoji Picker ────────────────────────────────────────────── */
+.emoji-picker-wrapper {
+    position: relative;
+}
+
+.emoji-picker {
+    position: absolute;
+    top: 100%;
+    right: 0;
+    background: #2c2d30;
+    border: 1px solid #444;
+    border-radius: 8px;
+    padding: 6px;
+    display: flex;
+    gap: 2px;
+    box-shadow: 0 4px 12px rgba(0,0,0,.5);
+    z-index: 20;
+}
+
+.emoji-option {
+    background: none;
+    border: none;
+    font-size: 1.25rem;
+    cursor: pointer;
+    padding: 4px 6px;
+    border-radius: 4px;
+    transition: background 0.15s;
+}
+
+.emoji-option:hover {
+    background: #444;
+}
+
+/* ── Compose Area ────────────────────────────────────────────── */
+.compose-area {
+    display: flex;
+    gap: 8px;
+    padding: 12px 20px;
+    border-top: 1px solid #333;
+    flex-shrink: 0;
+}
+
+.compose-input {
+    flex: 1;
+    background: #222529;
+    border: 1px solid #444;
+    border-radius: 6px;
+    padding: 8px 12px;
+    color: #d1d2d3;
+    font-size: 0.9rem;
+    resize: none;
+    min-height: 40px;
+    max-height: 120px;
+    font-family: inherit;
+}
+
+.compose-input:focus {
+    outline: none;
+    border-color: #1264a3;
+}
+
+.compose-input::placeholder {
+    color: #717274;
+}
+
+.send-btn {
+    background: #007a5a;
+    color: #fff;
+    border: none;
+    border-radius: 6px;
+    padding: 8px 16px;
+    font-weight: 600;
+    font-size: 0.85rem;
+    cursor: pointer;
+    align-self: flex-end;
+    transition: background 0.15s;
+}
+
+.send-btn:hover:not(:disabled) {
+    background: #148567;
+}
+
+.send-btn:disabled {
+    opacity: 0.4;
+    cursor: default;
+}
+
+/* ── Thread Panel ────────────────────────────────────────────── */
+.thread-panel {
+    width: 25%;
+    min-width: 260px;
+    max-width: 400px;
+    background: #222529;
+    border-left: 1px solid #333;
+    display: flex;
+    flex-direction: column;
+    overflow: hidden;
+}
+
+.thread-header {
+    display: flex;
+    align-items: center;
+    justify-content: space-between;
+    padding: 12px 16px;
+    border-bottom: 1px solid #333;
+    flex-shrink: 0;
+}
+
+.thread-header h4 {
+    margin: 0;
+    font-size: 1rem;
+    font-weight: 700;
+    color: #fff;
+}
+
+.close-btn {
+    background: none;
+    border: none;
+    color: #9a9b9e;
+    font-size: 1.1rem;
+    cursor: pointer;
+    padding: 4px 8px;
+    border-radius: 4px;
+}
+
+.close-btn:hover {
+    background: #333;
+    color: #fff;
+}
+
+.thread-root-quote {
+    padding: 12px 16px;
+    border-bottom: 1px solid #333;
+    background: #2c2d30;
+    flex-shrink: 0;
+}
+
+.thread-root-quote .msg-body {
+    margin-top: 4px;
+}
+
+.thread-replies {
+    flex: 1;
+    overflow-y: auto;
+    padding: 8px 16px;
+}
+
+.thread-reply {
+    padding: 6px 0;
+}
+
+.thread-panel .compose-area {
+    padding: 12px 16px;
+}
+
+/* ── Scrollbar styling ───────────────────────────────────────── */
+.message-list::-webkit-scrollbar,
+.thread-replies::-webkit-scrollbar,
+.channel-list::-webkit-scrollbar {
+    width: 6px;
+}
+
+.message-list::-webkit-scrollbar-track,
+.thread-replies::-webkit-scrollbar-track,
+.channel-list::-webkit-scrollbar-track {
+    background: transparent;
+}
+
+.message-list::-webkit-scrollbar-thumb,
+.thread-replies::-webkit-scrollbar-thumb,
+.channel-list::-webkit-scrollbar-thumb {
+    background: #555;
+    border-radius: 3px;
+}
+

